        offset = (packet - 1) * 7;
        for (i = 0; i < 7; i++)
            dt[i + 1] = offset + i < length ? data[offset + i] : 0xFF;
        dtcSendCanFrame(dtcMakeJ1939Id(6, 0x00EBFF, sourceAddress), dt, 8);
