static void dtcHandleRequest(const STCAN_MSG& rx)
{
    unsigned int id;
    unsigned char destination;
    unsigned char source;
    unsigned long requestedPgn;
    unsigned long mask = 0;
    int i;

    if (!rx.isExtended || rx.isRtr || rx.dlc < 3)
        return;
    id = rx.id;
    if (((id >> 16) & 0xFF) != 0xEA)
        return;
    requestedPgn = (unsigned long)rx.data[0] |
        ((unsigned long)rx.data[1] << 8) |
        ((unsigned long)rx.data[2] << 16);
    if (requestedPgn != 0x00FECB)
        return;

    destination = (unsigned char)((id >> 8) & 0xFF);
    source = (unsigned char)(id & 0xFF);
    EnterCriticalSection(&gDtcParamLock);
    gDtcLastRequestSource = source;
    gDtcLastRequestDestination = destination;
    for (i = 0; i < DTC_ECU_COUNT; i++)
    {
        if (gDtcEcu[i].enabled && (destination == 0xFF || destination == gDtcEcu[i].sourceAddress))
            mask |= 1UL << i;
    }
    LeaveCriticalSection(&gDtcParamLock);
    if (mask)
        dtcAtomicOr(&gDtcDm2RequestMask, (LONG)mask);
}

